use std::{fs,path::Path};use serde_json::{Value,json};use sha2::{Digest,Sha256};
fn main()->Result<(),Box<dyn std::error::Error>>{let arg=std::env::args().nth(1).ok_or("Directorio")?;let b=Path::new(&arg).join("diagnostico-A08-02");if b.join("UNICA-CARGA-ADMITIDA.json").exists()||b.join("config/ADMISION.json").exists(){return Err("Preparación ya admitida; no alterar".into())}
 let p=b.join("verificador/src/main.rs");let s=fs::read_to_string(&p)?;if s.matches("reasoning_effort=>\"medium\"").count()!=1{return Err("Patrón distinto".into())}fs::write(p,s.replace("reasoning_effort=>\"medium\"","reasoning_effort=>\"high\""))?;
 let mp=b.join("MANIFIESTO-PREPARACION.json");let mut m:Value=serde_json::from_slice(&fs::read(&mp)?)?;for f in m["archivos"].as_array_mut().ok_or("Archivos")?{let n=f["ruta"].as_str().ok_or("Ruta")?;let bytes=fs::read(b.join(n))?;f["bytes"]=json!(bytes.len());f["sha256"]=json!(format!("{:x}",Sha256::digest(bytes)));}fs::write(mp,serde_json::to_vec_pretty(&m)?)?;println!("Preparación D02 concordante entre emisor y verificador; manifiesto actualizado antes de admitir o compilar.");Ok(())}
